  SDLRenderer: PSDL_Renderer;
  Running: Boolean;
  Event: TSDL_Event;

  WindowWidth, WindowHeight: Integer;

begin
  // Inicjalizacja SDL
  if SDL_Init(SDL_INIT_VIDEO) < 0 then
  begin
    MessageBox(0, 'SDL could not initialize!', 'Error', MB_ICONERROR or MB_OK);
